def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    david_like_bid = 0.0
    desperate_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if oid == 'David':
                    david_like_bid = float(bid)

    if not alive_opps:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_ratio = (float(supply) - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22
    critical_me = hp <= 3 or no_water >= 1
    very_critical_me = hp <= 2 or no_water >= 2

    base = 24.0 + (1.0 - supply_ratio) * 12.0

    if david_like_bid > 0:
        target = david_like_bid + 1.2
    elif highest_prev > 0:
        target = highest_prev + 1.0
    else:
        target = 40.0 if tight_supply else 28.0

    if critical_me:
        bid = max(target, 58.0 if tight_supply else 48.0)
    else:
        if tight_supply:
            bid = max(base, target)
        elif loose_supply:
            bid = max(18.0, avg_prev * 0.75)
        else:
            bid = max(base, avg_prev * 0.9 + 2.0)

    if desperate_count >= 2 and not critical_me:
        bid *= 0.88

    if day >= 8:
        bid *= 1.08
    if very_critical_me:
        bid = max(bid, 72.0)

    safe_cap = budget
    if hp > 4 and no_water == 0:
        reserve = max(0.0, 2.0 * DAILY_SALARY)
        safe_cap = max(0.0, budget - reserve)
        if safe_cap <= 0:
            safe_cap = min(budget, 28.0 if loose_supply else 40.0)
    elif hp > 2 and no_water == 0:
        reserve = max(0.0, 1.0 * DAILY_SALARY)
        safe_cap = max(0.0, budget - reserve)
        if safe_cap <= 0:
            safe_cap = min(budget, 50.0)

    if critical_me:
        safe_cap = budget

    bid = min(bid, safe_cap, budget)
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = {oid: o for oid, o in opponents_status.items() if o['alive']}

    # Base bid: fraction of salary depending on supply scarcity
    if supply >= 22:
        base_bid = DAILY_SALARY * 0.3
    elif supply >= 18:
        base_bid = DAILY_SALARY * 0.45
    else:
        base_bid = DAILY_SALARY * 0.6

    # Adjust based on our own desperation
    if hp <= 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)
    elif hp <= 4:
        base_bid = max(base_bid, DAILY_SALARY * 0.7)

    # Opponent exploitation: use previous_trace
    max_opp_prev_bid = 0.0
    for oid, opp in alive_opponents.items():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev['bid']
            if bid > max_opp_prev_bid:
                max_opp_prev_bid = bid

    # If we know a high previous bid, respond appropriately
    if max_opp_prev_bid > 0:
        # If we are healthy, try to undercut or match
        if hp > 5:
            target = max(base_bid, max_opp_prev_bid + 0.5)
        else:
            target = max(base_bid, max_opp_prev_bid + 1.0)
    else:
        target = base_bid

    # Ensure we do not exceed budget (leave some reserve if possible)
    max_affordable = budget * 0.9  # Keep 10% reserve
    final_bid = min(target, max_affordable, DAILY_SALARY * 1.2)  # cap at 120% salary

    # Safety: never bid more than budget
    return min(final_bid, budget)
